mapper.update:
UPDATE task
title = #{title},
duedate = #{duedate},
group_seq = #{groupSeq},
modified_at = NOW(), modified_by = #{modifiedBy}
WHERE task_id = #{taskId}

UPDATE task
SET
deleted_yn = 'Y',
modified_at = NOW(),
modified_by = #{task.modifiedBy}
WHERE task_id = #{task.taskId}
AND deleted_yn = 'N'
AND group_seq in

    #{seq}

mapper.select:
SELECT task_id, task_status FROM ( SELECT t.task_id, tl.task_status FROM task t LEFT OUTER JOIN task_log tl on t.task_id = tl.task_id WHERE t.task_id = #{taskId} AND t.deleted_yn = 'N' AND group_seq in
#{seq}
ORDER BY tl.created_at DESC ) base LIMIT 1

SELECT base.task_id, base.title, base.duedate, base.created_at, u1.user_name as creator, base.modified_at, u2.user_name as modifier, g.group_name, base.task_log_id, base.task_status as task_log_status, base.task_created_at as task_log_created_at, u3.user_name as task_log_creator FROM ( SELECT t.task_id, t.title, t.duedate, t.created_at, t.created_by, t.modified_at, t.modified_by, t.group_seq, tl.task_log_id, tl.task_status, tl.created_at as task_created_at, tl.created_by as task_created_by FROM task t LEFT OUTER JOIN task_log tl on t.task_id = tl.task_id WHERE t.task_id = #{taskId} AND t.deleted_yn = 'N' AND group_seq in
#{seq}
ORDER BY tl.created_at DESC ) base LEFT OUTER JOIN users u1 on base.created_by = u1.user_seq LEFT OUTER JOIN users u2 on base.modified_by = u2.user_seq LEFT OUTER JOIN users u3 on base.task_created_by = u3.user_seq LEFT OUTER JOIN `groups` g on base.group_seq = g.group_seq
